-- =====================================================================
-- 487_tprm_baseline_seed_rollback.sql
--
-- Reverses 487 (GRAC baseline seed).
--   Removes the GRAC baseline lists, library, rules, risk model,
--   questionnaires and sample profiles when no organization data depends
--   on them.
--
-- Turn the API / Web change off first (or deploy the previous build): the
-- TPRM screens call the procedures this drops. Roll back in reverse
-- order: 490, 489, 488, 487, 486.
-- Generated by tools/tprm/gen_rollbacks.py from the objects 487 creates.
-- SAFE TO RE-RUN. ASCII-only.
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET NOEXEC OFF;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- Baseline rows (organization_id NULL) are removed only when nothing
-- depends on them: no organization override / addition rows, no adopted
-- templates and no engagements (488 rolled back). Otherwise the seed
-- stays and the script says so.
IF OBJECT_ID('grac_practice.tprm_reference_value','U') IS NOT NULL
BEGIN
    IF OBJECT_ID('grac_practice.tprm_engagement','U') IS NULL
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_reference_value WHERE organization_id IS NOT NULL)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_library_item WHERE organization_id IS NOT NULL)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_approval_rule WHERE organization_id IS NOT NULL)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_review_rule WHERE organization_id IS NOT NULL)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template WHERE organization_id IS NOT NULL)
    BEGIN
        UPDATE grac_practice.tprm_template SET current_version_id = NULL;
        DELETE o FROM grac_practice.tprm_q_option o JOIN grac_practice.tprm_q_question q ON q.question_id = o.question_id;
        DELETE FROM grac_practice.tprm_q_question;
        DELETE FROM grac_practice.tprm_q_section;
        DELETE FROM grac_practice.tprm_rm_tier_rule;
        DELETE FROM grac_practice.tprm_rm_band;
        DELETE FROM grac_practice.tprm_rm_factor_option;
        DELETE FROM grac_practice.tprm_rm_factor;
        DELETE FROM grac_practice.tprm_rm_dimension;
        DELETE FROM grac_practice.tprm_template_version;
        DELETE FROM grac_practice.tprm_template;
        DELETE FROM grac_practice.tprm_review_rule;
        DELETE FROM grac_practice.tprm_approval_rule;
        DELETE FROM grac_practice.tprm_library_item;
        DELETE FROM grac_practice.tprm_reference_value;
        DELETE FROM grac_practice.tprm_reference_list;
        PRINT '487 rollback: GRAC baseline rows removed.';
    END
    ELSE
        PRINT '487 rollback: organization configuration or engagements exist -- baseline kept.';
END
GO

IF OBJECT_ID('grac_practice.tprm_sample_profile','U') IS NOT NULL
   AND OBJECT_ID('grac_practice.tprm_third_party','U') IS NULL
BEGIN
    DROP TABLE grac_practice.tprm_sample_profile;
    PRINT '487 rollback: tprm_sample_profile dropped.';
END
GO

PRINT '487 rollback complete.';
GO
